import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [showQR, setShowQR] = useState(false);
  const [screenshot, setScreenshot] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false); // New: Prevent double clicks

  const [userId, setUserId] = useState("");
  const [approved, setApproved] = useState(false);
  const [photo, setPhoto] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* LOAD FACE MODEL */
  useEffect(() => {
    const loadModels = async () => {
      try {
        await faceapi.nets.tinyFaceDetector.loadFromUri("/models");
      } catch (err) {
        console.error("Face API models failed to load", err);
      }
    };
    loadModels();
  }, []);

  /* AUTO CHECK APPROVAL */
  useEffect(() => {
    let interval;
    if (userId && !approved) {
      interval = setInterval(async () => {
        try {
          const res = await axios.get(`http://localhost:5000/verify-user/${userId}`);
          if (res.data.success && res.data.user.payment_status === "approved") {
            setApproved(true);
            setStatusMsg("✅ Payment Approved! You can now generate your ID.");
            clearInterval(interval);
          }
        } catch (err) {
          console.log("Polling error:", err);
        }
      }, 5000);
    }
    return () => clearInterval(interval);
  }, [userId, approved]);

  /* INPUT */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* SHOW PAYMENT */
  const handlePayment = (e) => {
    e.preventDefault();
    setShowQR(true);
  };

  /* SUBMIT & DUPLICATE CHECK */
  const confirmPayment = async () => {
    if (!screenshot) return alert("Please select a payment screenshot!");
    
    setIsSubmitting(true);
    const form = new FormData();
    Object.keys(formData).forEach((key) => {
      form.append(key, formData[key]);
    });
    form.append("screenshot", screenshot);

    try {
      const res = await axios.post("http://localhost:5000/register", form, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setStatusMsg("⏳ Waiting for admin approval...");
      } else if (res.data.message === "Already Uploaded") {
        // This handles the case where the file or user is already registered
        setStatusMsg("❌ This payment file has already been uploaded!");
        alert("Duplicate detected: This file was already submitted.");
      }
    } catch (err) {
      // Logic for handling "Already Exists" if sent via 400 error
      if (err.response && err.response.data.message === "Already Uploaded") {
        alert("This file or user is already registered!");
      } else {
        alert("Upload failed. Please try again.");
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  /* CAMERA & PHOTO LOGIC */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch (err) {
      alert("Could not access camera");
    }
  };

  const capturePhoto = async () => {
    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length !== 1) {
      return alert("Please ensure exactly one face is visible in the camera.");
    }

    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    canvas.getContext("2d").drawImage(videoRef.current, 0, 0);
    
    setPhoto(canvas.toDataURL());
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }
  };

  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = `${formData.name}_ID_Card.png`;
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  const upiString = `upi://pay?pa=arunsekar664@okaxis&pn=Event&am=100&cu=INR`;

  // STYLES
  const box = { padding: "20px", borderRadius: "10px", background: "#222", width: "320px", margin: "20px auto" };
  const input = { padding: "10px", margin: "5px 0", width: "90%", borderRadius: "5px", border: "none" };
  const btn = { padding: "10px 20px", background: "orange", border: "none", cursor: "pointer", fontWeight: "bold", marginTop: "10px" };

  return (
    <div style={{ textAlign: "center", color: "white", backgroundColor: "#111", minHeight: "100vh" }}>
      <Navbar />
      <h2 style={{ marginTop: "20px" }}>🚀 Event Registration</h2>

      {/* STEP 1: INITIAL FORM */}
      {!showQR && (
        <form onSubmit={handlePayment} style={box}>
          <input name="name" placeholder="Full Name" style={input} onChange={handleChange} required />
          <input name="college_name" placeholder="College/University" style={input} onChange={handleChange} required />
          <input name="phone" placeholder="Phone Number" style={input} onChange={handleChange} required />
          <input name="email" placeholder="Email Address" style={input} onChange={handleChange} required />
          <h3 style={{ color: "orange" }}>{eventName}</h3>
          <button type="submit" style={btn}>Proceed to Pay</button>
        </form>
      )}

      {/* STEP 2: PAYMENT & WAITING */}
      {showQR && !approved && (
        <div style={box}>
          {!userId ? (
            <>
              <h3>Scan & Pay</h3>
              <QRCode value={upiString} size={200} bgColor="#fff" />
              <p style={{ fontSize: "12px", margin: "10px" }}>Upload the payment screenshot below:</p>
              <input type="file" accept="image/*" onChange={(e) => setScreenshot(e.target.files[0])} style={{ color: "white" }} />
              <button style={btn} onClick={confirmPayment} disabled={isSubmitting}>
                {isSubmitting ? "Uploading..." : "Submit Payment"}
              </button>
            </>
          ) : (
            <div style={{ padding: "20px" }}>
              <h3 style={{ color: "yellow" }}>Status: Pending</h3>
              <p>{statusMsg}</p>
              <p>Please wait while the admin verifies your payment.</p>
            </div>
          )}
        </div>
      )}

      {/* STEP 3: PHOTO CAPTURE AFTER APPROVAL */}
      {approved && !photo && (
        <div style={box}>
          <h3 style={{ color: "lime" }}>Payment Approved!</h3>
          <p>Now, let's take your photo for the ID card.</p>
          {!streamRef.current?.active ? (
            <button style={btn} onClick={openCamera}>Start Camera</button>
          ) : (
            <>
              <video ref={videoRef} style={{ width: "100%", borderRadius: "10px", marginBottom: "10px" }} />
              <button style={btn} onClick={capturePhoto}>Capture Photo</button>
            </>
          )}
          <canvas ref={canvasRef} style={{ display: "none" }} />
        </div>
      )}

      {/* STEP 4: FINAL ID CARD */}
      {photo && (
        <div style={{ paddingBottom: "40px" }}>
          <div ref={idCardRef} style={{ background: "white", color: "black", padding: "20px", width: "300px", margin: "20px auto", borderRadius: "15px", boxShadow: "0 0 20px rgba(255,255,255,0.2)" }}>
            <h2 style={{ margin: "0", color: "#333" }}>EVENT PASS</h2>
            <hr />
            <img src={photo} alt="User" style={{ width: "120px", height: "120px", borderRadius: "50%", border: "3px solid orange", marginTop: "10px" }} />
            <h3 style={{ marginBottom: "5px" }}>{formData.name}</h3>
            <p style={{ margin: "0", fontWeight: "bold" }}>{eventName}</p>
            <p style={{ fontSize: "12px", color: "gray" }}>College: {formData.college_name}</p>
            <div style={{ marginTop: "15px" }}>
              <QRCode value={userId} size={80} />
            </div>
            <p style={{ fontSize: "10px", marginTop: "10px" }}>ID: {userId}</p>
          </div>
          <button style={btn} onClick={downloadCard}>Download ID Card</button>
        </div>
      )}
    </div>
  );
}

export default Register;
